		right = lri[1],
		index = lri[2];

	if (left > right) continue;

	let i = index;
	while (indices[i] < left || indices[i] > right) i++;
	let ind = indices[i];

	sum += A[ind] * (ind - left + 1) * (right - ind + 1);
	if (left <= ind - 1) que[que.length] = [left, ind - 1, i + 1];
	if (ind + 1 <= right) que[que.length] = [ind + 1, right, i + 1];
}

